functions.Hisense_GetChromiumVersion:
function() {
        var arr = navigator.userAgent.split(' ')
        var chromiumVersion = ''
        for (var i = 0; i < arr.length; i++) {
            if (/chrome/i.test(arr[i])) { chromiumVersion = arr[i] }
        }
        if (chromiumVersion) {
            return Number(chromiumVersion.split('/')[1].split('.')[0])
        }

        return 0
    }

