functions.Hisense_RegisterObserver:
function(key, callback) {
        console.log('Hisense_SetObserver.')
        if (key == '' || key == null || key == undefined || typeof callback != 'function') {
            console.log('unvalid param!')
            return false
        }
        return TvInfo_setParamObserver(key, callback)
    }

functions.Hisense_UnregisterObserver:
function(key) {
        if (key == '' || key == null || key == undefined) {
            console.log('unvalid param!')
            return false
        }
        return TvInfo_clearParamObserver(key)
    }

